  public void Tick(DeviceInventory inventory){if(!Busy&&!disposed&&Engine.VirtualPathFailed){var restore=Stop();Status="虚拟声卡输出异常，已停止并尝试恢复原输出。 / Virtual output failed; restoring output.";return;}var states=Engine.Snapshot();foreach(var s in phones.Sessions.Values.Where(s=>s.Managed&&!Busy)){var state=states.FirstOrDefault(x=>x.Source==s.Id);bool connected=state!=null&&state.Status=="running";if(s.Connected!=connected||s.Status!=(connected?"connected":"error")){s.Connected=connected;phones.Revision++;if(connected)phones.Remember(s.Id);}s.Status=connected?"connected":"error";s.Detail=state==null?Status:state.Error;}
