   if(settings.Test||disposed||Busy||!ResumePending||inventory==null||DateTime.UtcNow<next)return;attempts++;next=DateTime.UtcNow.AddSeconds(Math.Min(30,5*Math.Pow(2,Math.Min(3,attempts-1))));
   try{var saved=SettingsStore.Clone(settings.Get<RunningGraph>("LastRunningGraph"));if(saved==null||saved.Schema!=1)throw new ArgumentException("Invalid saved graph schema");var plan=GraphPlan.Create(saved.Edges,saved.Modules);GraphRuntime.ValidateLivePlan(plan,settings.Bool("VirtualCableEnabled"));
    foreach(string id in plan.Sources.Concat(plan.Outputs)){if(id=="o:default"&&!inventory.Endpoints.Any(e=>e.Active&&e.IsDefault))throw new InvalidOperationException("等待默认输出 / Waiting for default output");if((id.StartsWith("o:")||id.StartsWith("c:"))&&(settings.IsIgnored("endpoint:"+id.Substring(2))||inventory.Devices.Any(d=>(d.EndpointId==id.Substring(2)||d.CaptureId==id.Substring(2))&&settings.IsIgnored(d.Id))))throw new InvalidOperationException("设备已忽略 / Device ignored");if(id.StartsWith("p:")&&(!phones.Sources.Any(s=>s.Id==id.Substring(2))||phones.IsIgnored(id.Substring(2))||!phones.CanCapture(id.Substring(2))))throw new InvalidOperationException("等待手机就绪 / Waiting for phone");if((id.StartsWith("o:")||id.StartsWith("c:"))&&id!="o:default"&&!inventory.Endpoints.Concat(inventory.Captures).Any(e=>e.Id==id.Substring(2)&&e.Active))throw new InvalidOperationException("等待音频设备 / Waiting for device");}
