  }
  RememberedApp[] RememberApplications(GraphPlan plan){var saved=settings.Get<RunningGraph>("LastRunningGraph");return plan.NativeAppEdges.Select(e=>e.Source).Distinct().Select(id=>{var binding=settings.Items<AppBinding>("AudioAppNodes").FirstOrDefault(a=>a.Source==id);var old=saved==null?null:(saved.Applications??new RememberedApp[0]).FirstOrDefault(a=>a.Id==id);return new RememberedApp{Id=id,Path=binding!=null&&!String.IsNullOrEmpty(binding.Path)?binding.Path:old!=null&&!String.IsNullOrEmpty(old.Path)?old.Path:ProcessPath(id)};}).ToArray();}
